{
  "items": [
    {
      "name": "Polynomial.natDegree_hasseDeriv_le",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree ≤ p.natDegree - n"
    },
    {
      "name": "Polynomial.degree_derivative_le",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, (Polynomial.derivative p).degree ≤ p.degree"
    },
    {
      "name": "Polynomial.natDegree_iterate_derivative",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (k : ℕ),\n  ((⇑Polynomial.derivative)^[k] p).natDegree ≤ p.natDegree - k"
    },
    {
      "name": "Polynomial.derivative'",
      "module_name": "Mathlib.Algebra.Polynomial.Derivation",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommSemiring R] → Derivation R (Polynomial R) (Polynomial R)"
    },
    {
      "name": "Polynomial.derivative",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.iterate_derivative_eq_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R} {x : ℕ}, p.natDegree < x → (⇑Polynomial.derivative)^[x] p = 0"
    },
    {
      "name": "Polynomial.natDegree_derivative_le",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), (Polynomial.derivative p).natDegree ≤ p.natDegree - 1"
    },
    {
      "name": "Polynomial.degree_derivative_eq",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [IsAddTorsionFree R] (p : Polynomial R),\n  0 < p.natDegree → (Polynomial.derivative p).degree = ↑(p.natDegree - 1)"
    }
  ]
}
